<script setup lang="ts">
const api=window.teachshelf;
import {computed,ref,watch} from 'vue';
import {Download,ExternalLink,FileSearch,FileText,Globe} from 'lucide-vue-next';
import type {WebsiteResult} from '../../shared/api';
import {useLibrary} from '../stores/library';
import Modal from './Modal.vue';
const props=defineProps<{initialKind?:'teaching'|'timetable'}>();
const emit=defineEmits<{close:[]}>(),store=useLibrary(),kind=ref<'teaching'|'timetable'>(props.initialKind??'teaching'),result=ref<WebsiteResult|null>(null),selected=ref<string[]>([]),localCourseID=ref(store.courseID??''),summary=ref('');
const connection=store.state.teachingConnections.find(c=>c.courseID===store.courseID);
const url=ref(kind.value==='timetable'?'https://ehallapp.nju.edu.cn/jwapp/sys/wdkb/*default/index.do':connection?.remoteCourseID?`https://selearning.nju.edu.cn/course/view.php?id=${connection.remoteCourseID}`:'https://selearning.nju.edu.cn/');
interface TeachingFile {key:string;name:string;url:string;subfolders?:string[]}
interface TeachingActivity {id:string;title:string;url:string;kind:string}
const page=computed(()=>result.value?.data&&typeof result.value.data==='object'?result.value.data as Record<string,unknown>:{});
const files=computed(()=>Array.isArray(page.value.files)?page.value.files.filter((f):f is TeachingFile=>!!f&&typeof f==='object'&&typeof f.key==='string'&&typeof f.name==='string'&&typeof f.url==='string'):[]);
const activities=computed(()=>Array.isArray(page.value.activities)?page.value.activities.filter((a):a is TeachingActivity=>!!a&&typeof a==='object'&&typeof a.title==='string'&&typeof a.url==='string'&&typeof a.id==='string'):[]);
watch(kind,k=>{url.value=k==='teaching'?'https://selearning.nju.edu.cn/':'https://ehallapp.nju.edu.cn/jwapp/sys/wdkb/*default/index.do';result.value=null;selected.value=[];summary.value='';});
async function open(target=url.value){await store.run(()=>api.openWebsite(target,kind.value),'教学网站窗口已打开');url.value=target;result.value=null;selected.value=[];summary.value='';}
async function inspect(){const value=await store.run(()=>api.inspectWebsite(kind.value),'当前页面已解析');if(value){result.value=value;selected.value=[];summary.value='';}}
function selectAll(){selected.value=selected.value.length===files.value.length?[]:files.value.map(f=>f.key);}
async function importSelected(){if(!result.value?.proposalID||!selected.value.length)return;const proposalID=result.value.proposalID;const imported=await store.run(()=>api.importWebsite({proposalID,courseID:localCourseID.value||undefined,fileKeys:[...selected.value]}),'网站资料导入完成');if(imported){await store.refresh();summary.value=`已导入 ${imported.imported} 份，跳过 ${imported.skipped} 份`;store.status=summary.value;if(imported.errors.length)store.error=imported.errors.join('\n');selected.value=[];}}
async function importSchedule(){const proposalID=result.value?.proposalID;if(!proposalID)return;const imported=await store.run(()=>api.importTimetable(proposalID),'课表已导入');if(imported){store.accept(imported.snapshot);store.status=`已导入 ${imported.summary.meetingsImported} 个上课时段，新建 ${imported.summary.coursesCreated} 门课程`;store.navigate('timetable');emit('close');}}
const pretty=computed(()=>JSON.stringify(result.value?.data,null,2));
</script>
<template><Modal title="教学网站" wide @close="emit('close')"><div class="form-stack"><p class="muted">在独立窗口完成登录并打开课程或课表页面，再回到此处读取。</p><div class="form-row"><label>网站类型<select aria-label="网站类型" v-model="kind"><option value="teaching">教学平台（Moodle）</option><option value="timetable">南京大学课表</option></select></label><label class="grow">页面地址<input v-model="url" type="url"/></label></div><div class="setting-actions"><button class="primary" @click="open()" :disabled="!!store.busy"><ExternalLink :size="15"/>打开登录窗口</button><button @click="inspect" :disabled="!!store.busy"><FileSearch :size="15"/>读取当前页面</button></div><div class="info-note"><Globe :size="17"/><span>教学网页运行在隔离窗口。读取页面后，选中的资料才会下载到本地。导入前会重新核对账号和页面；课程绑定及全局更新审核尚未迁移。</span></div><div v-if="result" class="website-result"><h3>{{String(page.title??result.title??'页面解析结果')}}</h3><p class="small muted wrap">{{result.url}}</p><template v-if="kind==='teaching'"><div v-if="activities.length" class="website-activities"><p class="field-note">打开课件、作业或实验条目后，点击“读取当前页面”查看可下载文件。</p><button v-for="activity in activities" :key="activity.kind+activity.id" @click="open(activity.url)"><FileText :size="16"/><span>{{activity.title}}</span><ExternalLink :size="13"/></button></div><div v-if="files.length" class="website-files"><div class="website-files-header"><label class="check-label"><input type="checkbox" :checked="selected.length===files.length" @change="selectAll"/>选择全部 {{files.length}} 个文件</label><span class="small muted">已选 {{selected.length}} 个</span></div><label v-for="file in files" :key="file.key" class="website-file-row"><input type="checkbox" :value="file.key" v-model="selected"/><FileText :size="17"/><span>{{file.name}}<small v-if="file.subfolders?.length">{{file.subfolders.join(' / ')}}</small></span></label><div class="website-import"><label>导入到课程<select aria-label="导入到课程" v-model="localCourseID"><option value="">未分类</option><option v-for="c in store.state.courses" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="primary" @click="importSelected" :disabled="!selected.length||!!store.busy"><Download :size="15"/>导入选中资料</button></div><p class="field-note">导入清单在读取后 15 分钟内有效；已有文件由主进程检查并跳过。</p></div><p v-if="!activities.length&&!files.length" class="info-note">当前页面未找到课件条目或可下载文件，请确认已登录并打开具体课程。</p><p v-if="summary" class="import-summary">{{summary}}</p></template><template v-else><p class="info-note">核对解析结果后，可将本课表导入资料库。同名学期会更新上课时段并保留已设置的学期日期和停课、调课记录。</p><pre>{{pretty}}</pre><div class="dialog-actions"><span class="spacer"/><button class="primary" @click="importSchedule" :disabled="!result.proposalID||!!store.busy"><Download :size="15"/>导入本课表</button></div></template></div></div></Modal></template>
